def balanced_strings(n: int, max_depth: int) -> list[str]:
    res, path = [], []

    def bt(opened: int, closed: int) -> None:
        if closed == n:
            res.append("".join(path))
            return
        if opened < n and opened - closed < max_depth:
            path.append("(")             # room for one more, and not too deep
            bt(opened + 1, closed)
            path.pop()
        if closed < opened:
            path.append(")")             # only close what is open
            bt(opened, closed + 1)
            path.pop()

    bt(0, 0)
    return res

perf.naive:
from itertools import product


def balanced_strings(n: int, max_depth: int) -> list[str]:
    res = []
    for chars in product("()", repeat=2 * n):    # every string of 2n brackets
        depth, ok = 0, True
        for ch in chars:
            depth += 1 if ch == "(" else -1
            if depth < 0 or depth > max_depth:
                ok = False
                break
        if ok and depth == 0:
            res.append("".join(chars))
    return res
